  content = '{"title":"The First Lock","screenTitle":"The First Lock","roleIsolated":true,"narrativeObjective":"Synthesize Stage 1 findings to name the shared handling class that closes the first stage.","coordinationChain":{"observerProduces":"Observer confirms the shared custody annotation - AMBIENT - is present across all five exhibits.","analystTransforms":"Analyst matches that annotation against the class register and finds the one class it names.","operatorExecutes":"Operator checks the custody policy, which defines that class, and confirms the class name."},"operatorInvestigation":{"operatorOwnEvidence":"Bureau custody policy defining evidence classes.","operatorTaskDescription":"Confirm the class name that applies to all five files."},"hints":["One annotation repeats across all five Stage 1 files. Read it off the top of each file before you look at any class list.","The class register lists five classes; exactly one of them is the class for evidence logged under that same annotation.","The custody policy defines that class as standard evidence observed under ordinary ambient light - which is the class name you submit."],"observer":{"role":"observer","screenTitle":"Cross-Exhibit Check","dataPayload":"The five Stage 1 exhibits are examined together. Each one - the plate, the poster register, the roster, the signature block and the custody slip - carries the identical custody annotation AMBIENT stamped at its head. No exhibit carries any other custody annotation.","whatTheySee":"A single custody annotation, AMBIENT, repeated on every exhibit.","taskPrompt":"Confirm the annotation is present on every exhibit.","intermediateOutput":"All five exhibits carry the same annotation, AMBIENT."},"analyst":{"role":"analyst","screenTitle":"Class Register","dataPayload":"BUREAU CLASS REGISTER, evidence handling classes: SEALED - evidence held under court seal and never opened. FLASH - evidence observed under a single bright flash and immediately stored. LIGHT - standard evidence observed under ordinary ambient light. DARK - evidence observed only in darkness. DEEP - evidence held under more than one archive. Exactly one of these classes applies to evidence annotated AMBIENT.","whatTheySee":"A class register whose five entries describe handling conditions rather than content.","taskPrompt":"Match the repeated annotation to the one registered class it names.","intermediateOutput":"The AMBIENT annotation names the LIGHT class."},"operator":{"role":"operator","screenTitle":"Custody Policy","dataPayload":"CUSTODY POLICY: the policy defines each class by the condition under which the evidence was observed. The class for evidence observed under ordinary ambient light is defined in the policy as the handling class the archive applies to any exhibit annotated AMBIENT. Submit the class name that matches all five files.","whatTheySee":"The policy''s definition of the class that applies to AMBIENT evidence.","taskPrompt":"Confirm the class name that applies to all five files.","intermediateOutput":"Awaiting the team conclusion."},"operatorInvestigation":{"operatorOwnEvidence":"The Bureau custody policy, which defines the class for evidence observed under ordinary ambient light.","operatorTaskDescription":"Confirm the class name that applies to all five files."},"requiredDiscoveries":{"observerDiscovery":"Reads the shared AMBIENT annotation off every exhibit.","analystDiscovery":"Matches AMBIENT to the single class the register names for it."}}',
  answer_metadata = '{"acceptedAnswer":"LIGHT","presentedEvidence":true,"answerType":"text","caseSensitive":true,"normalization":"strip_non_alnum","validation":{"pattern":"^[A-Za-z]{5}$","minLength":5,"maxLength":5},"fullSolution":"All five Stage 1 exhibits carry the same custody annotation, AMBIENT. The class register lists five handling classes - SEALED, FLASH, LIGHT, DARK, DEEP - and exactly one is the class for standard evidence observed under ordinary ambient light: LIGHT. The custody policy defines that same class as the one applied to any exhibit annotated AMBIENT, so the shared class for the whole stage is LIGHT."}',
  metadata = '{"type":"META","difficulty":4,"time":"12m","storyReveal":"All five files were logged into the programme under one custody class, the Bureau''s class for evidence held in ordinary light, and the stage closes on its name.","locationClue":{"format":"Narrative","clueText":"Proceed to the basement east stairwell.","solution":"Basement East Stairwell","nextPhysicalLocation":"[LIBRARY] - Basement East Stairwell","nextQrNode":"QR-NODE-06","explanation":"Directs the team from the stage-1 files to the basement east stairwell."},"evidenceUnlocked":{"id":"EVID-M01","category":"Document","title":"Stage 1 Class Determination","state":"RECOVERED","timestamp":"Stage 1","source":"Stage 1 file set","content":"Every Stage 1 exhibit was annotated AMBIENT and logged under the single Bureau handling class LIGHT: standard evidence observed under ordinary ambient light."},"whyTeamworkMatters":"Only the observer sees the annotation repeated on every exhibit; only the analyst matches it against the register; only the operator confirms the policy definition and the class name."}'
